'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, byId, currentView='archive', activeCharacter=null, limit=20, kind='all', secrets=false, compare=[], bookmarks=new Set(), bondId='gong-suyin', zoom=1, pan={x:0,y:0};
const featured=['yan-wuchen','gong-suyin','heavenly-demon-venerable','endless-despair','wen-ruxue','lin-zhenyu','lin-xiaoman','heavenly-sword-sovereign'];
const meaningful=v=>v&&v!=='Unrecorded'&&v!=='Unaffiliated';
const paragraphs=text=>String(text||'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
function sections(text){return String(text||'').split(/\n(?=[A-Z][A-Za-z /—-]{2,40}:\s*\n)/).map(block=>{const m=block.match(/^([^\n:]{2,50}):\s*\n([\s\S]*)/);return m?`<h4>${esc(m[1])}</h4>${paragraphs(m[2])}`:paragraphs(block)}).join('')}
function safeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2800)}
function visibleEdges(){return data.edges.filter(e=>secrets||e.scope!=='hidden')}
function connections(id,mode='lore'){
 const c=byId.get(id);if(!c)return [];
 if(mode!=='lore'){const field=mode==='faction'?'faction':'location';if(!meaningful(c[field]))return [];return data.characters.filter(o=>o.id!==id&&o[field]===c[field]).map(o=>({id:o.id,records:[{scope:'known',text:`Both characters are recorded ${field==='faction'?'as members of':'at'} ${c[field]}.`,kind:field}]}));}
 const map=new Map();for(const e of visibleEdges()){if(e.source!==id&&e.target!==id)continue;const other=e.source===id?e.target:e.source;if(other===id)continue;if(!map.has(other))map.set(other,{id:other,records:[]});if(!map.get(other).records.some(r=>r.text===e.text))map.get(other).records.push(e)}
 return [...map.values()].sort((a,b)=>byId.get(a.id).name.localeCompare(byId.get(b.id).name));
}
function publicCorpus(c){return [c.name,c.type,c.realm,c.faction,c.location,c.basicInfo,c.summary,...(c.traits||[]),secrets?c.hiddenInfo:''].join(' ').toLowerCase()}
function renderArchive(){
 const q=$('#search').value.trim().toLowerCase(), realm=$('#realm-filter').value, faction=$('#faction-filter').value;
 let chars=data.characters.filter(c=>(kind==='all'||(kind==='saved'?bookmarks.has(c.id):c.kind===kind))&&(!realm||c.realm===realm)&&(!faction||c.faction===faction)&&(!q||q.split(/\s+/).every(t=>publicCorpus(c).includes(t))));
 const sort=$('#sort').value;const counts=new Map();if(sort==='connections')for(const c of chars)counts.set(c.id,connections(c.id).length);
 chars.sort((a,b)=>sort==='connections'?(counts.get(b.id)-counts.get(a.id)||a.name.localeCompare(b.name)):sort==='featured'?((featured.includes(a.id)?featured.indexOf(a.id):100)-(featured.includes(b.id)?featured.indexOf(b.id):100)||a.name.localeCompare(b.name)):a.name.localeCompare(b.name));
 $('#result-count').textContent=`${chars.length} ${chars.length===1?'soul':'souls'} found · ${Math.min(limit,chars.length)} revealed`;
 $('#empty-state').hidden=chars.length!==0;$('#load-more').hidden=chars.length<=limit;
 $('#character-grid').innerHTML=chars.slice(0,limit).map(c=>`<article class="character-card"><button class="card-image-button" data-open="${c.id}" aria-label="Read ${esc(c.name)}’s record"><img src="${esc(c.thumbnail||c.image)}" alt="Portrait of ${esc(c.name)}" loading="lazy" width="300" height="400"><span class="card-realm">${esc(c.realm==='Unrecorded'?'A LIFE UNWRITTEN':c.realm.toUpperCase())}</span></button><button class="bookmark-button ${bookmarks.has(c.id)?'saved':''}" data-bookmark="${c.id}" aria-label="${bookmarks.has(c.id)?'Remove bookmark for':'Bookmark'} ${esc(c.name)}" aria-pressed="${bookmarks.has(c.id)}">${bookmarks.has(c.id)?'◆':'◇'}</button><div class="card-description"><div class="card-heading"><button class="card-name" data-open="${c.id}">${esc(c.name)}</button><button class="compare-button ${compare.includes(c.id)?'selected':''}" data-compare="${c.id}" aria-label="${compare.includes(c.id)?'Remove':'Select'} ${esc(c.name)} for comparison" aria-pressed="${compare.includes(c.id)}">${compare.includes(c.id)?'✓':'+'}</button></div><p class="card-faction">${esc(meaningful(c.faction)?c.faction:c.kind==='premade'?'Premade life · a beginning, not a destiny':'No recorded allegiance')}</p><p class="card-summary">${esc(c.summary)}</p><div class="card-meta"><span>${c.kind==='npc'?'WORLD CHARACTER':'PREMADE CHARACTER'}</span><span>${connections(c.id).length} THREADS ↗</span></div></div></article>`).join('');
 updateTray();
}
function resetFilters(){kind='all';limit=20;$('#search').value='';$('#realm-filter').value='';$('#faction-filter').value='';$('#sort').value='featured';$$('[data-kind]').forEach(b=>{b.classList.toggle('active',b.dataset.kind==='all');b.setAttribute('aria-pressed',b.dataset.kind==='all')});renderArchive()}
function updateTray(){const names=compare.map(id=>byId.get(id)?.name).filter(Boolean);$('#nav-count').textContent=names.length;$('#tray-label').textContent=names.length===1?`${names[0]} · choose one more`:names.join(' × ');$('#compare-tray').hidden=!names.length||currentView==='compare';$('#compare-a').value=compare[0]||'';$('#compare-b').value=compare[1]||''}
function toggleCompare(id){if(compare.includes(id))compare=compare.filter(v=>v!==id);else if(compare.length<2)compare.push(id);else{toast('Two souls are selected. Remove one or change the selection in Compare souls.');return}safeStore('defy-compare',compare);renderArchive();if(activeCharacter)renderDetail(activeCharacter);if(currentView==='compare')renderCompare();updateTray()}
function toggleBookmark(id){bookmarks.has(id)?bookmarks.delete(id):bookmarks.add(id);safeStore('defy-bookmarks',[...bookmarks]);renderArchive();if(activeCharacter)renderDetail(activeCharacter);toast(bookmarks.has(id)?'A name kept in memory.':'Bookmark removed.')}
function renderDetail(id){const c=byId.get(id);if(!c)return;const rel=connections(id);const faction=data.factions.find(f=>f.name===c.faction);$('#detail-content').innerHTML=`<div class="detail-layout"><div class="detail-portrait"><img src="${esc(c.image)}" alt="${esc(c.name)}"></div><div class="detail-body"><p class="eyebrow">${c.kind==='premade'?'A LIFE YET TO BE LIVED':'FROM THE WORLD RECORDS'} / ${esc(c.realm)}</p><h2 id="detail-name">${esc(c.name)}</h2><p class="detail-type">${esc(c.type||c.gender)}${meaningful(c.faction)?' · '+esc(c.faction):''}</p><div class="detail-actions"><button class="outline" data-compare="${c.id}">${compare.includes(c.id)?'✓ Selected for comparison':'+ Compare this soul'}</button><button class="outline" data-bookmark="${c.id}">${bookmarks.has(c.id)?'◆ Bookmarked':'◇ Bookmark'}</button><button class="text-button" data-share="${c.id}">Copy link ↗</button></div><div class="shared-tags">${[c.cultivation,c.location].filter(meaningful).map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div><section class="lore-section"><h3>A life beneath heaven</h3>${sections(c.basicInfo||c.summary)}</section>${c.traits?.length?`<section class="lore-section"><h3>Marks of a life</h3><div class="shared-tags">${c.traits.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></section>`:''}${c.abilities?.length?`<section class="lore-section"><h3>What they have learned</h3>${c.abilities.map(a=>`<p>${esc(a)}</p>`).join('')}</section>`:''}${c.hiddenInfo?(secrets?`<section class="lore-section"><p class="eyebrow">UNSEALED / STORY SPOILERS</p><h3>What lies beneath</h3>${sections(c.hiddenInfo)}</section>`:`<div class="secret-note">◇ Hidden motives and private attachments are sealed.<button class="text-button" data-secrets>Unseal hidden lore ↗</button></div>`):''}<section class="lore-section"><h3>Threads of fate</h3><p>${rel.length?'Names connected through the recorded lore. Select one to read their life.':'No named character connection is recorded in the currently visible lore.'}</p><div class="related-links">${rel.map(r=>`<button data-open="${r.id}">${esc(byId.get(r.id).name)} ↗</button>`).join('')}</div><button class="text-button" data-follow="${c.id}">Trace these threads ↗</button></section>${faction?`<section class="lore-section"><p class="eyebrow">ALLEGIANCE</p><h3>${esc(faction.name)}</h3>${paragraphs(faction.basicInfo)}${secrets&&faction.hiddenInfo?`<h4>Concealed faction history</h4>${paragraphs(faction.hiddenInfo)}`:''}</section>`:''}</div></div>`;}
function openCharacter(id){if(!byId.has(id))return;activeCharacter=id;renderDetail(id);if(!$('#character-dialog').open)$('#character-dialog').showModal();$('#character-dialog').scrollTop=0;history.replaceState(null,'',`#character=${encodeURIComponent(id)}`)}
function closeCharacter(){activeCharacter=null;$('#character-dialog').close();history.replaceState(null,'','#'+currentView)}
function requestSecrets(){if(secrets){secrets=false;refreshSecrets()}else $('#secret-dialog').showModal()}
function refreshSecrets(){const b=$('#spoiler-toggle');b.innerHTML=`<span class="lock-icon" aria-hidden="true">${secrets?'◆':'◇'}</span> ${secrets?'Secrets unsealed':'Secrets sealed'}`;b.setAttribute('aria-pressed',secrets);renderArchive();if(activeCharacter)renderDetail(activeCharacter);if(currentView==='bonds')renderBonds();if(currentView==='compare')renderCompare();toast(secrets?'Hidden lore is now visible.':'Hidden lore is sealed.')}
function graphTransform(){const group=$('#graph-world');if(group)group.setAttribute('transform',`translate(${420+pan.x} ${310+pan.y}) scale(${zoom}) translate(-420 -310)`)}
function renderBonds(){const c=byId.get(bondId)||data.characters[0];bondId=c.id;$('#bond-person').value=bondId;const mode=$('#bond-mode').value, rel=connections(bondId,mode),shown=rel.slice(0,12);$('#bond-name').textContent=c.name;$('#bond-subtitle').textContent=[c.realm,c.faction].filter(meaningful).join(' · ');$('#graph-count').textContent=`${rel.length} ${mode==='lore'?'lore connections':mode==='faction'?'faction companions':'shared-location records'}${rel.length>12?' · 12 pictured, all listed':''}`;
 $('#connection-list').innerHTML=rel.length?rel.map(r=>`<article class="connection-item"><button data-bond="${r.id}">${esc(byId.get(r.id).name)} ↗</button>${r.records.slice(0,2).map(e=>`<small>${e.scope==='hidden'?'UNSEALED LORE':mode==='lore'?'RECORDED LORE':mode==='faction'?'SHARED FACTION':'SHARED LOCATION'}</small><p>${esc(e.text)}</p>`).join('')}</article>`).join(''):`<div class="connection-item"><p>No ${mode==='lore'?'named connections in the visible lore':mode==='faction'?'shared faction':'shared location'} are recorded. ${mode==='lore'&&!secrets&&c.hiddenInfo?'Hidden lore remains sealed.':''}</p></div>`;
 const nodes=[{c,x:420,y:290,center:true},...shown.map((r,i)=>{const angle=-Math.PI/2+i*2*Math.PI/Math.max(shown.length,1);return {c:byId.get(r.id),x:420+285*Math.cos(angle),y:290+224*Math.sin(angle),center:false}})];
 $('#relation-graph').setAttribute('role','group');$('#relation-graph').innerHTML=`<defs>${nodes.map((n,i)=>`<clipPath id="clip-${i}"><circle cx="${n.x}" cy="${n.y}" r="${n.center?61:35}"/></clipPath>`).join('')}</defs><g id="graph-world"><circle cx="420" cy="290" r="220" fill="none" stroke="#758264" stroke-opacity=".11" stroke-dasharray="2 9"/><circle cx="420" cy="290" r="100" fill="none" stroke="#758264" stroke-opacity=".1"/>${nodes.slice(1).map(n=>`<line class="graph-edge" x1="420" y1="290" x2="${n.x}" y2="${n.y}"/>`).join('')}${nodes.map((n,i)=>`<g class="graph-node ${n.center?'center':''}" data-bond="${n.c.id}" role="button" tabindex="0" aria-label="${n.center?'Read':'Follow connections for'} ${esc(n.c.name)}"><circle cx="${n.x}" cy="${n.y}" r="${n.center?65:38}" fill="#151b13"/><image href="${esc(n.c.thumbnail||n.c.image)}" x="${n.x-(n.center?61:35)}" y="${n.y-(n.center?61:35)}" width="${n.center?122:70}" height="${n.center?122:70}" preserveAspectRatio="xMidYMid slice" clip-path="url(#clip-${i})"/><text x="${n.x}" y="${n.y+(n.center?91:59)}">${esc(n.c.name)}</text></g>`).join('')}</g>`;graphTransform();
}
function routeBetween(a,b){const adj=new Map();for(const e of visibleEdges()){if(!adj.has(e.source))adj.set(e.source,new Set());if(!adj.has(e.target))adj.set(e.target,new Set());adj.get(e.source).add(e.target);adj.get(e.target).add(e.source)}const queue=[[a]],seen=new Set([a]);for(let i=0;i<queue.length;i++){const path=queue[i];if(path.at(-1)===b)return path;if(path.length>6)continue;for(const n of adj.get(path.at(-1))||[])if(!seen.has(n)){seen.add(n);queue.push([...path,n])}}return null}
function renderCompare(){updateTray();const [a,b]=compare.map(id=>byId.get(id));const profile=c=>c?`<article class="compare-profile"><div class="compare-top"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><small>${esc(c.realm)}</small><h3>${esc(c.name)}</h3><p>${esc(c.type||c.gender)}</p><button class="text-button" data-open="${c.id}">Read full record ↗</button></div></div><div class="compare-facts">${[['Allegiance',meaningful(c.faction)?c.faction:'No recorded allegiance'],['Cultivation',c.cultivation||'Not specified in the record'],['Where they stand',c.location||'Unrecorded'],['Their story',c.summary],['Character',c.basicInfo.match(/Personality:\s*([\s\S]*?)(?=\n[A-Z][^\n:]+:\s*\n|$)/)?.[1]||c.traits?.join(' · ')||'Read the full record for this life.'],...(secrets&&c.hiddenInfo?[['Beneath the surface',c.hiddenInfo.match(/Core Drive:\s*([^\n]+)/)?.[1]||c.hiddenInfo.split('\n\n')[0]]]:[])].map(([k,v])=>`<div class="fact"><span>${esc(k.toUpperCase())}</span><p>${esc(v)}</p></div>`).join('')}</div></article>`:`<div class="compare-empty"><h3>An unchosen life</h3><p>Choose a soul above or select + in the archive.</p></div>`;
 let shared='';if(a&&b){const direct=visibleEdges().filter(e=>(e.source===a.id&&e.target===b.id)||(e.source===b.id&&e.target===a.id));const tags=[];if(meaningful(a.faction)&&a.faction===b.faction)tags.push('Shared faction · '+a.faction);if(meaningful(a.realm)&&a.realm===b.realm)tags.push('Shared realm · '+a.realm);if(meaningful(a.location)&&a.location===b.location)tags.push('Shared location · '+a.location);const ar=connections(a.id).map(r=>r.id), br=connections(b.id).map(r=>r.id), common=ar.filter(id=>br.includes(id));const path=routeBetween(a.id,b.id);shared=`<section class="shared"><p class="eyebrow">WHERE THEIR LIVES TOUCH</p><h3>${direct.length?'A thread in the record':'Between two lives'}</h3><div class="shared-tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${direct.length?direct.map(e=>`<article class="connection-item"><small>${e.scope==='hidden'?'UNSEALED':'PUBLIC'} LORE · ${esc(byId.get(e.source).name)}’S RECORD</small><p>${esc(e.text)}</p></article>`).join(''):`<article class="connection-item"><p>No direct named connection is recorded in the currently visible lore. Shared places or factions do not, by themselves, establish friendship or enmity.</p></article>`}${common.length?`<div class="connection-item"><small>SHARED LORE CONNECTIONS</small><div class="related-links">${common.map(id=>`<button data-open="${id}">${esc(byId.get(id).name)} ↗</button>`).join('')}</div></div>`:''}${path&&path.length>2?`<div class="connection-item"><small>A PATH THROUGH THE RECORDS · NOT A DIRECT RELATIONSHIP</small><div class="related-links">${path.map(id=>`<button data-open="${id}">${esc(byId.get(id).name)} →</button>`).join('')}</div></div>`:''}${!secrets?'<p class="muted" style="font-size:10px">Hidden lore is sealed. Unsealing may reveal further connections.</p>':''}</section>`}
 $('#comparison-content').innerHTML=`<div class="compare-profiles">${profile(a)}${profile(b)}</div>${shared}`;
}
function route(){const hash=location.hash.slice(1);if(hash.startsWith('character=')){openCharacter(decodeURIComponent(hash.slice(10)));return}const [part,query]=hash.split('?');currentView=['bonds','compare'].includes(part)?part:'archive';if(activeCharacter){activeCharacter=null;$('#character-dialog').close()}if(currentView==='compare'&&query){const params=new URLSearchParams(query);compare=[params.get('a'),params.get('b')].filter((id,i,all)=>byId.has(id)&&all.indexOf(id)===i)}$$('.view').forEach(el=>el.hidden=el.id!==currentView+'-view');$('#hero').hidden=currentView!=='archive';$$('.nav-link').forEach(a=>a.classList.toggle('active',a.hash==='#'+currentView));if(currentView==='bonds')renderBonds();if(currentView==='compare')renderCompare();updateTray();if(part!=='archive-list')window.scrollTo({top:0,behavior:'instant'});}
function pickCompare(){let a=$('#compare-a').value,b=$('#compare-b').value;if(a&&a===b){toast('Choose two different souls.');b='';$('#compare-b').value=''}compare=[a,b].filter(Boolean);safeStore('defy-compare',compare);renderCompare();history.replaceState(null,'',`#compare${compare.length?'?a='+encodeURIComponent(compare[0])+(compare[1]?'&b='+encodeURIComponent(compare[1]):''):''}`)}
function follow(id){if(id===bondId&&currentView==='bonds'){openCharacter(id);return}bondId=id;zoom=1;pan={x:0,y:0};if(activeCharacter)closeCharacter();if(currentView!=='bonds')location.hash='bonds';else renderBonds()}
async function init(){try{const res=await fetch('data.json');if(!res.ok)throw Error('Archive unavailable');data=await res.json();byId=new Map(data.characters.map(c=>[c.id,c]));try{bookmarks=new Set(JSON.parse(localStorage.getItem('defy-bookmarks')||'[]').filter(id=>byId.has(id)));compare=JSON.parse(localStorage.getItem('defy-compare')||'[]').filter((id,i,a)=>byId.has(id)&&a.indexOf(id)===i).slice(0,2)}catch{};
 $('#stat-characters').textContent=data.characters.length;$('#stat-factions').textContent=data.factions.length;$('#stat-realms').textContent=data.realms.length;$('#all-count').textContent=data.characters.length;
 const option=(value,label=value)=>`<option value="${esc(value)}">${esc(label)}</option>`;
 $('#realm-filter').innerHTML+= [...new Set(data.characters.map(c=>c.realm))].sort().map(r=>option(r,r==='Unrecorded'?'Unrecorded realm':r)).join('');$('#faction-filter').innerHTML+=[...new Set(data.characters.map(c=>c.faction).filter(meaningful))].sort().map(f=>option(f)).join('');
 const opts=[...data.characters].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>option(c.id,c.name)).join('');$('#bond-person').innerHTML=opts;$('#compare-a').innerHTML=option('','Choose a soul…')+opts;$('#compare-b').innerHTML=option('','Choose a soul…')+opts;
 $('#load-state').hidden=true;$('#source-note').textContent=`Authored world records · ${data.sourceDate||'10 October 2026'} · Hidden lore sealed by default`;
 $('#search').addEventListener('input',()=>{limit=20;renderArchive()});['#realm-filter','#faction-filter','#sort'].forEach(s=>$(s).addEventListener('change',()=>{limit=20;renderArchive()}));$('#reset-filters').onclick=resetFilters;$('#empty-reset').onclick=resetFilters;
 $$('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;limit=20;$$('[data-kind]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderArchive()});$('#load-more').onclick=()=>{limit+=20;renderArchive()};$('#featured').onclick=()=>openCharacter('yan-wuchen');$('#close-dialog').onclick=closeCharacter;$('#character-dialog').addEventListener('cancel',e=>{e.preventDefault();closeCharacter()});$('#character-dialog').addEventListener('click',e=>{if(e.target===$('#character-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeCharacter()}});
 $('#spoiler-toggle').onclick=requestSecrets;$('#keep-sealed').onclick=()=>$('#secret-dialog').close();$('#unseal').onclick=()=>{secrets=true;$('#secret-dialog').close();refreshSecrets()};$('#bond-person').onchange=()=>{bondId=$('#bond-person').value;zoom=1;pan={x:0,y:0};renderBonds()};$('#bond-mode').onchange=renderBonds;$('#bond-profile').onclick=()=>openCharacter(bondId);$('#bond-reset').onclick=()=>{zoom=1;pan={x:0,y:0};graphTransform()};$('#zoom-in').onclick=()=>{zoom=Math.min(2,zoom+.2);graphTransform()};$('#zoom-out').onclick=()=>{zoom=Math.max(.6,zoom-.2);graphTransform()};$('#compare-a').onchange=pickCompare;$('#compare-b').onchange=pickCompare;$('#swap').onclick=()=>{compare.reverse();renderCompare();safeStore('defy-compare',compare)};const clear=()=>{compare=[];safeStore('defy-compare',compare);renderArchive();renderCompare();if(activeCharacter)renderDetail(activeCharacter)};$('#clear-compare').onclick=clear;$('#tray-clear').onclick=clear;
 document.addEventListener('click',async e=>{const target=e.target.closest('[data-open],[data-compare],[data-bookmark],[data-follow],[data-bond],[data-secrets],[data-share]');if(!target)return;if(target.dataset.open)openCharacter(target.dataset.open);else if(target.dataset.compare)toggleCompare(target.dataset.compare);else if(target.dataset.bookmark)toggleBookmark(target.dataset.bookmark);else if(target.dataset.follow)follow(target.dataset.follow);else if(target.dataset.bond)follow(target.dataset.bond);else if(target.hasAttribute('data-secrets'))requestSecrets();else if(target.dataset.share){try{await navigator.clipboard.writeText(location.href);toast('Character link copied.')}catch{toast('Copy the character link from your address bar.')}}});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();if(currentView!=='archive')location.hash='archive';$('#search').focus()}if(['Enter',' '].includes(e.key)&&e.target.matches('.graph-node')){e.preventDefault();follow(e.target.dataset.bond)}});
 let drag=null;$('#relation-graph').addEventListener('pointerdown',e=>{if(e.target.closest('.graph-node'))return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};e.currentTarget.setPointerCapture(e.pointerId)});$('#relation-graph').addEventListener('pointermove',e=>{if(!drag)return;const scale=840/e.currentTarget.getBoundingClientRect().width;pan={x:drag.px+(e.clientX-drag.x)*scale,y:drag.py+(e.clientY-drag.y)*scale};graphTransform()});$('#relation-graph').addEventListener('pointerup',()=>drag=null);$('#relation-graph').addEventListener('pointercancel',()=>drag=null);
 window.addEventListener('hashchange',route);renderArchive();route();
 }catch(error){$('#load-state').innerHTML='<div class="error-state"><h2>The archive could not be opened.</h2><p>Please reload the page to try again.</p><button class="outline" onclick="location.reload()">Retry</button></div>';console.error(error)}}
init();
